	servers := []Server{{Name: "api", Port: 8080}}
	for i, srv := range servers {
		if srv.Port > 0 && i < 10 {
			fmt.Println(strings.ToUpper(srv.Addr()), nil, true)
		}
	}
}

fn main() {
    let items = vec![1, 2, 3];
    let total: i32 = items.iter().map(|x| x * 2).sum();
    println!("{} {}", total, items.len());
}

